{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>{{BUSINESS_NAME}} — {{TAGLINE}}</title>
  <meta name="description" content="A sensory, premium series of sound bath gatherings in {{CITY}}, {{STATE}}. Next event: {{NEXT_EVENT_DATE}}." />
  <link rel="stylesheet" href="/assets/css/styles.css">
  <script defer src="/assets/js/main.js"></script>
</head>
<body class="layout-split">
  <header class="site-header">
    <div class="brand">
      <a href="/" class="logo">{{BUSINESS_NAME}}</a>
      <small class="tag">{{TAGLINE}}</small>
    </div>
    <nav class="main-nav">
      <a href="/events.html">Gatherings</a>
      <a href="/private-sessions.html">1:1 & Private</a>
      <a href="/pricing.html">Investment</a>
      <a href="/about.html">Our Story</a>
      <a href="/faq.html">Questions</a>
      <a href="/book.html" class="cta">{{PRIMARY_CTA_LABEL}}</a>
      <a href="/contact.html" class="muted">Reach</a>
    </nav>
    <button class="nav-toggle" aria-label="menu">☰</button>
  </header>

  <main>
    <!-- HERO (split diagonal) -->
    <section class="hero" id="hero">
      <svg class="hero-pattern" aria-hidden="true"><use href="/assets/img/pattern.svg#tile"/></svg>
      <div class="hero-inner">
        <div class="hero-copy">
          <h1>Sound as a doorway.</h1>
          <p class="lead">A curated series of sound baths — deliberate resonance, guided surrender. Join us in {{CITY}} for a premium sensory journey crafted by {{FACILITATOR_NAME}} at {{VENUE_NAME}}.</p>
          <div class="hero-meta">
            <div class="next">Next event: <time class="next-event" data-next="{{NEXT_EVENT_DATE}}">{{NEXT_EVENT_DATE}}</time></div>
            <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          </div>
        </div>
        <div class="hero-visual" aria-hidden="true">
          <div class="card">
            <p class="micro">Sonic palette</p>
            <ul class="instruments">
              <li>Crystal bowls</li>
              <li>Chimes</li>
              <li>Gong</li>
              <li>Tuning forks</li>
            </ul>
          </div>
        </div>
      </div>
    </section>

    <!-- MYTH VS TRUTH -->
    <section class="myth-truth">
      <div class="container">
        <h2>Myth vs. truth — a quiet guide</h2>
        <div class="split">
          <div>
            <h3>Myth</h3>
            <p>Sound baths are background music for relaxation only — soft and unstructured.</p>
          </div>
          <div>
            <h3>Truth</h3>
            <p>Every session is intentional: layered instruments, measured pacing, and cues that support safe embodiment. We design a flow that takes you from arrival to rest to gentle return.</p>
          </div>
        </div>
      </div>
    </section>

    <!-- PILLARS -->
    <section class="pillars">
      <div class="container">
        <h2>Three pillars of our gatherings</h2>
        <ul class="grid">
          <li>
            <h4>Sonic architecture</h4>
            <p>We arrange tone and space — from deep gong valleys to crystalline overtone fields — so sound becomes a structure you can inhabit.</p>
          </li>
          <li>
            <h4>Somatic care</h4>
            <p>Clear guidance, pacing for nervous systems, and accessible options make the work restorative and safe.</p>
          </li>
          <li>
            <h4>Intentional ritual</h4>
            <p>Simple prompts and a steady sequence create a reliable frame for letting go and integration.</p>
          </li>
        </ul>
      </div>
    </section>

    <!-- CASE NOTES (testimonials + flow) -->
    <section class="case-notes" id="case-notes">
      <div class="container">
        <h2>What a session feels like</h2>
        <ol class="flow">
          <li><strong>Arrive & settle:</strong> soft lighting, grounding breath, intention-setting.</li>
          <li><strong>Entry:</strong> warm, low tones invite the body to release and soften.</li>
          <li><strong>Immersion:</strong> layered instruments — waves of sound that create a felt landscape.</li>
          <li><strong>Return:</strong> gentle reconnection with breath and light movement; a short integration period.</li>
        </ol>

        <h3>Guest notes</h3>
        <blockquote class="note">“I found a depth I hadn’t expected — like stepping into a slow-motion ocean.” — A participant</blockquote>

        <div class="what-to-bring">
          <h4>What to bring</h4>
          <ul>
            <li>Yoga mat or low-profile mattress</li>
            <li>Blanket and small pillow for neck support</li>
            <li>Water bottle and an open heart</li>
            <li>Eye mask or cosy scarf (optional)</li>
          </ul>
        </div>

        <p class="disclaimer"><strong>Contraindications:</strong> If you are pregnant, have a history of epilepsy, severe cardiac conditions, or are sensitive to intense sound, please consult your healthcare provider and contact us before attending. Some instruments may produce strong vibrations; facilitators adapt sessions as needed.</p>
      </div>
    </section>

    <!-- FAQ -->
    <section class="faq">
      <div class="container">
        <h2>Questions folks often ask</h2>
        <div class="qa">
          <details>
            <summary>Is this session therapeutic or medical?</summary>
            <p>These gatherings are not a substitute for medical or mental health care. They are somatic and sensory experiences intended for relaxation and integration.</p>
          </details>
          <details>
            <summary>How long is a typical event?</summary>
            <p>Our public events run ~75 minutes: arrival (10–15 min), sound immersion (50–60 min), gentle return (10–15 min).</p>
          </details>
          <details>
            <summary>Can I move during the session?</summary>
            <p>Yes. Many participants rest, some shift posture, and a few move gently. You are invited to follow your comfort and the facilitator's cues.</p>
          </details>
        </div>
      </div>
    </section>

    <!-- CALL TO ACTION -->
    <section class="cta">
      <div class="container">
        <h2>Reserve a place in the next circle</h2>
        <p>Space is intentionally limited. Book early to ensure a comfortable, spacious experience.</p>
        <div class="cta-actions">
          <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <a class="btn hollow" href="/events.html">See upcoming dates</a>
        </div>
      </div>
    </section>

  </main>

  <footer class="site-footer">
    <div class="container">
      <p>Hosted by {{FACILITATOR_NAME}} at {{VENUE_NAME}} — <a href="tel:{{PHONE}}">{{PHONE}}</a> · <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
      <nav class="foot-nav">
        <a href="/about.html">About</a>
        <a href="/pricing.html">Pricing</a>
        <a href="/contact.html">Contact</a>
      </nav>
      <small class="credits">&copy; <span id="year"></span> {{BUSINESS_NAME}}</small>
    </div>
  </footer>

</body>
</html>","_verbatim":false}
