{"path":"assets/css/styles.css","content":"/* Minimal, poetic, split-diagonal layout with rich gradients and SVG pattern */
:root{--bg:#0f1720;--card:#0b1220;--accent:#f6e8d6;--muted:#a8b3bf;--accent-2:#8bd3c7}
*{box-sizing:border-box}
html,body{height:100%;margin:0;font-family:Inter, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial; color:var(--accent);background:linear-gradient(180deg,#071018 0%, #081222 50%);}
.container{max-width:1100px;margin:0 auto;padding:3rem}
.site-header{display:flex;align-items:center;justify-content:space-between;padding:1rem 2rem;position:sticky;top:0;background:linear-gradient(180deg,rgba(11,17,24,0.6),rgba(11,17,24,0.2));backdrop-filter:blur(6px);z-index:40}
.brand .logo{font-weight:700;color:var(--accent);text-decoration:none;font-size:1.1rem}
.brand .tag{display:block;color:var(--muted);font-size:.8rem}
.main-nav{display:flex;gap:1rem;align-items:center}
.main-nav a{color:var(--muted);text-decoration:none;padding:.25rem .5rem;border-radius:6px}
.main-nav a.cta{background:linear-gradient(90deg,var(--accent-2),#72c8d9);color:#072024;font-weight:600}
.nav-toggle{display:none;background:none;border:0;color:var(--accent);font-size:1.4rem}

/* HERO */
.hero{position:relative;overflow:hidden;padding:4rem 0}
.hero .hero-pattern{position:absolute;inset:0;width:100%;height:100%;opacity:.08;mix-blend-mode:overlay}
.hero-inner{display:grid;grid-template-columns:1fr 420px;gap:2rem;align-items:center;padding:4rem 0}
.hero-copy h1{font-size:clamp(2.2rem,4vw,3.6rem);margin:0 0 .5rem;color:var(--accent)}
.hero-copy .lead{color:var(--muted);max-width:52ch}
.hero-meta{margin-top:1.25rem;display:flex;gap:1rem;align-items:center}
.btn{display:inline-block;padding:.6rem 1rem;border-radius:8px;text-decoration:none}
.btn.primary{background:linear-gradient(90deg,#d6f8ef,#bdebe7);color:#042;font-weight:700}
.btn.hollow{border:1px solid rgba(255,255,255,0.06);color:var(--muted);background:transparent}

.hero-visual .card{background:linear-gradient(180deg,rgba(255,255,255,0.02),rgba(255,255,255,0.01));border-radius:14px;padding:1rem;width:100%;color:var(--muted);box-shadow:0 10px 30px rgba(2,6,23,0.6)}
.instruments{list-style:none;padding:0;margin:.5rem 0 0;display:grid;gap:.25rem}
.instruments li{background:linear-gradient(90deg,rgba(255,255,255,0.02),transparent);padding:.35rem .6rem;border-radius:6px;color:var(--accent-2);font-weight:600}

/* Diagonal split effect */
.layout-split main{position:relative}
.layout-split .hero::after{content:"";position:absolute;right:-40%;top:-10%;width:140%;height:120%;background:linear-gradient(120deg,rgba(130,116,255,0.06),rgba(139,211,199,0.03));transform:rotate(-12deg);pointer-events:none;mix-blend-mode:screen}

/* Sections */
section{padding:3rem 0;border-top:1px solid rgba(255,255,255,0.02)}
.myth-truth .split{display:grid;grid-template-columns:1fr 1fr;gap:2rem}
.pillars .grid{display:grid;grid-template-columns:repeat(3,1fr);gap:1.25rem;margin-top:1rem}
.pillars h4{color:var(--accent-2)}
.case-notes .flow{list-style:decimal;padding-left:1.25rem;color:var(--muted)}
.note{border-left:2px solid rgba(189,235,231,0.12);padding-left:1rem;color:var(--accent-2);font-style:italic}
.what-to-bring ul{list-style:disc;margin-left:1.25rem;color:var(--muted)}
.disclaimer{margin-top:1rem;color:#f3c6b8;background:linear-gradient(90deg,rgba(243,198,184,0.03),transparent);padding:.75rem;border-radius:8px}

.faq .qa details{background:rgba(255,255,255,0.01);padding:.6rem;border-radius:8px;margin-bottom:.5rem}
.faq summary{cursor:pointer;color:var(--accent)}

.cta{background:linear-gradient(180deg,rgba(8,15,24,0.6),rgba(8,15,24,0.3));text-align:center;padding:3.5rem 0}
.cta-actions{display:flex;gap:1rem;justify-content:center;margin-top:1rem}

.site-footer{padding:2rem;border-top:1px solid rgba(255,255,255,0.02);color:var(--muted)}
.foot-nav a{margin-right:1rem;color:var(--muted);text-decoration:none}

/* Responsive */
@media (max-width:900px){
  .hero-inner{grid-template-columns:1fr;}
  .main-nav{display:none}
  .nav-toggle{display:block}
}
@media (max-width:600px){
  .container{padding:1.25rem}
  .pillars .grid{grid-template-columns:1fr}
}
"},"_verbatim":false}
{"path":"assets/js/main.js","content":"(function(){
  // Simple UI behaviors: year, nav toggle, FAQ, next event label
  document.addEventListener('DOMContentLoaded',function(){
    var year = document.getElementById('year'); if(year) year.textContent = new Date().getFullYear();

    // Nav toggle for small screens
    var toggle = document.querySelector('.nav-toggle');
    var nav = document.querySelector('.main-nav');
    if(toggle && nav){
      toggle.addEventListener('click',function(){
        nav.style.display = nav.style.display === 'flex' ? 'none' : 'flex';
      });
    }

    // FAQ native details styling helper
    var details = document.querySelectorAll('.faq details');
    details.forEach(function(d){
      d.addEventListener('toggle',function(){
        if(d.open){ d.style.boxShadow = '0 6px 20px rgba(2,6,23,0.6)'; } else { d.style.boxShadow = 'none'; }
      });
    });

    // Inject next event date from data attribute (placeholder kept for templating)
    var next = document.querySelector('.next-event');
    if(next){
      var val = next.getAttribute('data-next') || '{{NEXT_EVENT_DATE}}';
      next.textContent = val;
    }

    // Smooth scroll for anchor links
    document.querySelectorAll('a[href^="#"]').forEach(function(a){
      a.addEventListener('click',function(e){
        var target = document.querySelector(this.getAttribute('href'));
        if(target){ e.preventDefault(); target.scrollIntoView({behavior:'smooth'}); }
      });
    });
  });
})();"},"_verbatim":false}
